mapper.select:
SELECT id, run_id, agent_code, user_id, session_id, execution_mode, input_text, input_context, status, output_text, output_metadata, error_code, error_message, duration_ms, started_time, finished_time, created_time, updated_time FROM agent_run
user_id = #{userId}
ORDER BY created_time DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, run_id, agent_code, user_id, session_id, execution_mode, input_text, input_context, status, output_text, output_metadata, error_code, error_message, duration_ms, started_time, finished_time, created_time, updated_time FROM agent_run WHERE run_id = #{runId}
AND user_id = #{userId}
LIMIT 1

SELECT id, run_id, agent_code, user_id, session_id, execution_mode,
       input_text, input_context, status, output_text, output_metadata,
       error_code, error_message, duration_ms, started_time, finished_time,
       created_time, updated_time
FROM agent_run
WHERE user_id = #{userId}
  AND agent_code = #{agentCode}
  AND session_id = #{sessionId}
  AND status = 'SUCCEEDED'
  AND output_text IS NOT NULL
ORDER BY created_time DESC, id DESC
LIMIT #{limit}
